#include <iostream>

using std::cout;
using std::cin;
using std::endl;

int main()
{
    int iNumber = 0;
    int iSum = 0;

    cout << "0 이상의 정수를 입력하세요: ";
    cin >> iNumber;

    do
    {
        iSum += iNumber % 10;
        iNumber /= 10;
    } while (iNumber > 0);

    cout << "각 자리 숫자의 합: " << iSum << endl;

    return 0;
}
